    private IntegrityInspection inspectIntegrity(Path folderPath, Path indexPath, Properties properties,
                                                 RuleViolationFileNameStrategy namingStrategy) {
        Path folderRealPath;
        try {
            folderRealPath = folderPath.toRealPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }

        List<Entry> entries = properties.stringPropertyNames().stream()
                .map(description -> new Entry(description, properties.getProperty(description)))
                .sorted(Comparator.comparing(entry -> entry.description))
                .collect(toList());

        for (Entry entry : entries) {
            entry.resolve(folderPath, folderRealPath);
            // Random names are assigned only when a new rule is stored. There is no meaningful
            // derived name to compare for an existing entry in that mode.
            entry.derivedName = randomFileNames ? entry.name :
                    requireRuleFileName(namingStrategy.createRuleFileName(entry.description));
            entry.misplaced = !entry.name.equals(entry.derivedName);
            entry.occupied = entry.misplaced && isOccupied(folderPath, folderRealPath, entries, entry);
            if (entry.directRegularFile) {
                try {
                    entry.resolved = readLines(entry.targetPath).isEmpty();
                } catch (RuntimeException e) {
                    entry.broken = true;
                }
            } else {
                entry.broken = true;
            }
        }

        markShared(entries);
        List<String> unownedFiles = findUnownedFiles(folderRealPath, entries);
        List<Entry> colliding = entries.stream()
                .filter(entry -> entries.stream().anyMatch(other -> other != entry && entry.derivedName.equals(other.derivedName)))
                .collect(toList());
        return new IntegrityInspection(entries, colliding, unownedFiles);
    }

    private String requireRuleFileName(String fileName) {
