    private boolean isOccupied(Path folderPath, Path folderRealPath, List<Entry> entries, Entry entry) {
        if (entries.stream().anyMatch(other -> other != entry && entry.derivedName.equals(other.name))) {
            return true;
        }
        try {
            Path derivedPath = resolvePath(folderPath, entry.derivedName);
            if (!isDirectPath(derivedPath, folderPath, folderRealPath)) {
                return true;
            }
            return pathExistsWithoutFollowingLinks(derivedPath);
        } catch (RuntimeException e) {
            return true;
        }
    }

    private void markShared(List<Entry> entries) {
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                Entry first = entries.get(i);
                Entry second = entries.get(j);
                if (first.name.equals(second.name) || sameFile(first.targetPath, second.targetPath)) {
                    first.shared = true;
                    second.shared = true;
                }
            }
        }
    }

    private List<String> findUnownedFiles(Path folderRealPath, List<Entry> entries) {
        List<String> result = new ArrayList<>();
        try (DirectoryStream<Path> files = Files.newDirectoryStream(folderRealPath)) {
            for (Path file : files) {
                if (file.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
                    continue;
                }
                if (!Files.isRegularFile(file)) {
                    continue;
                }
                boolean owned = entries.stream().anyMatch(entry -> sameFile(entry.targetPath, file));
                if (!owned) {
                    result.add(file.getFileName().toString());
