    }

    private void repairIntegrity(Path folderPath, Path indexPath, Properties properties, IntegrityInspection inspection) {
        boolean entryChanged = false;
        for (Entry entry : inspection.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken || entry.resolved) {
                if (entry.resolved && !sameFile(entry.targetPath, indexPath)) {
                    deleteEntryFile(entry);
                }
                properties.remove(entry.description);
                entryChanged = true;
            }
        }
        for (Entry entry : inspection.entries) {
            if (entry.shared || entry.broken || entry.resolved || !entry.misplaced || entry.occupied ||
                    inspection.colliding.contains(entry)) {
                continue;
            }
            try {
                moveEntryFile(folderPath, entry);
                properties.setProperty(entry.description, entry.derivedName);
                entryChanged = true;
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
