        synchronized (storeState.lock) {
            String description = rule.getDescription();
            Properties properties = storeState.loadedProperties;
            String existingFileName = properties.getProperty(description);
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existingFileName != null) {
                forgetRule(description, existingFileName, properties);
                return;
            }

            String ruleFileName = existingFileName;
            if (ruleFileName == null) {
                ruleFileName = requireRuleFileName(createRuleFileName(description));
            }
            WriteTarget target = validateWriteTarget(ruleFileName, existingFileName, properties);
            byte[] contents = encodeViolations(violations);
            byte[] oldContents = null;
            boolean targetExisted = pathExistsWithoutFollowingLinks(target.path);
            try {
                if (targetExisted && Files.isRegularFile(target.path)) {
                    oldContents = Files.readAllBytes(target.writePath);
                }
                Files.write(target.writePath, contents, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
