            if (existingFileName == null) {
                properties.setProperty(description, ruleFileName);
                try {
                    syncProperties(storeState.indexFile.toPath(), properties);
                } catch (RuntimeException e) {
                    properties.remove(description);
                    restoreFile(target, targetExisted, oldContents);
                    throw e;
